struct RingBuffer {
    int buf[1024];
    int cap;
    int head;
    int tail;
    int count;

    RingBuffer(int capacity) : cap(capacity), head(0), tail(0), count(0) {}

    bool push(int value) {
        if (count == cap) return false;
        buf[tail] = value;
        tail = (tail + 1) % cap;
        ++count;
        return true;
    }

    bool pop(int& out) {
        if (count == 0) return false;
        out = buf[head];
        head = (head + 1) % cap;
        --count;
        return true;
    }

    int size() const { return count; }
    bool empty() const { return count == 0; }
    bool full() const { return count == cap; }
};
