        grads.push_back(0.0);
        return (int)nodes.size() - 1;
    }
    int add(int a, int b) {
        nodes.push_back({nodes[a].val + nodes[b].val, 2, a, b});
        grads.push_back(0.0);
        return (int)nodes.size() - 1;
    }
    int mul(int a, int b) {
        nodes.push_back({nodes[a].val * nodes[b].val, 3, a, b});
        grads.push_back(0.0);
        return (int)nodes.size() - 1;
    }
    int sin_(int a) {
        nodes.push_back({std::sin(nodes[a].val), 4, a, -1});
        grads.push_back(0.0);
        return (int)nodes.size() - 1;
    }
    int exp_(int a) {
        nodes.push_back({std::exp(nodes[a].val), 5, a, -1});
        grads.push_back(0.0);
        return (int)nodes.size() - 1;
    }
    double value(int node) const { return nodes[node].val; }

    void backward(int root) {
