  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wq1_rgray <= 0;
      wq2_rgray <= 0;
    end else begin
      wq1_rgray <= rgray;
      wq2_rgray <= wq1_rgray;
    end
  end

  // ---- read clock domain ----
  always @(posedge rclk or negedge rrst_n) begin
